fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // Ensure both arrays have the same length
    assert_eq!(arr1.len(), arr2.len(), "Input arrays must have the same length");

    // Create a new vector to store the results
    let mut result = Vec::with_capacity(arr1.len());

    // Iterate over the elements of both arrays
    for (&num1, &num2) in arr1.iter().zip(arr2.iter()) {
        // Perform integer division and push the result to the new vector
        result.push(num1 / num2);
    }

    result
}